; off.asm -- chapter 20: seven loops, the display off
; generated by gen20.py
        INCLUDE "msx.inc"
        OUTPUT "off.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
BOX_EMPTY EQU 1             ; the library's two boxes, characters 1 and 2
BOX_FULL  EQU 2
; 64 bytes of text written with seven loops, 18 to 31 T-states a byte, with
; the display off; then the display on, to show them.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, l18
        call puts
        ld b, 3
        ld c, 0
        ld hl, l23
        call puts
        ld b, 6
        ld c, 0
        ld hl, l25
        call puts
        ld b, 9
        ld c, 0
        ld hl, l26
        call puts
        ld b, 12
        ld c, 0
        ld hl, l27
        call puts
        ld b, 15
        ld c, 0
        ld hl, l29
        call puts
        ld b, 18
        ld c, 0
        ld hl, l31
        call puts
s18:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1820        ; 40
        DUP 64
        outi                    ; 18
        EDUP
z18:
s23:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1880        ; 40
        ld b, 64
        otir                    ; 23 a byte, 18 the last
z23:
s25:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $18E0        ; 40
        DUP 64
        ld a, (hl)              ;  8
        inc l                   ;  5
        out (VDP_DATA), a       ; 12: 25
        EDUP
z25:
s26:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1940        ; 40
        DUP 64
        outi                    ; 18
        ld a, (hl)              ;  8: 26, and A is not used
        EDUP
z26:
s27:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $19A0        ; 40
        DUP 64
        ld a, (hl)              ;  8
        inc hl                  ;  7
        out (VDP_DATA), a       ; 12: 27
        EDUP
z27:
s29:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1A00        ; 40
        ld b, 64
x29:   outi                    ; 18
        jp nz, x29           ; 11: 29
z29:
s31:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1A60        ; 40
        ld b, 64
x31:   outi                    ; 18
        jr nz, x31           ; 13: 31
z31:
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done
l18:        db "OUTI, UNROLLED: 18 T A BYTE", 0
l23:        db "OTIR: 23 T A BYTE", 0
l25:        db "LD A,(HL)/INC L/OUT: 25 T", 0
l26:        db "OUTI/LD A,(HL), UNROLLED: 26 T", 0
l27:        db "LD A,(HL)/INC HL/OUT: 27 T", 0
l29:        db "OUTI/JP NZ: 29 T A BYTE", 0
l31:        db "OUTI/JR NZ: 31 T A BYTE", 0
        ALIGN 256
text:   db "ABCDEFGHIJKLMNOPQRSTUVWXYZ012345ABCDEFGHIJKLMNOPQRSTUVWXYZ012345"

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
